-- The MULTI-FEED-MASTER code key (Code keys -> Milling -> MULTI-FEED-MASTER), from the ISCAR
-- e-catalog's MULTI-FEED-MASTER families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.multifeedmaster', $ck${"title": "MULTI-FEED-MASTER code key – FEED-MILL heads", "subtitle": "Interchangeable solid carbide FEED-MILL heads on the MULTI-MASTER threaded connection, for milling at very fast feeds and a small depth of cut", "example": "MM EFF080T3R1.62-4T05", "decoder": "multi-feed-master", "sections": [{"key": "t-family", "title": "Head – family", "sample": "EFF", "rows": [{"code": "FF", "meaning": "2 flute FEED-MILL heads"}, {"code": "EFF", "meaning": "4, 6 flute FEED-MILL heads"}]}, {"key": "t-dia", "title": "Head – diameter", "rows": [{"code": "###", "meaning": "Cutting diameter x10 (e.g. 080 = 8 mm)"}, {"code": ".##", "meaning": "Cutting diameter in inches"}]}, {"key": "t-geometry", "title": "Head – geometry", "rows": [{"code": "S", "meaning": "Geometry S (see the catalog)"}, {"code": "T", "meaning": "Geometry T (see the catalog)"}, {"code": "A", "meaning": "Geometry A (see the catalog)"}]}, {"key": "t-dims", "title": "Head – dimension code", "rows": [{"code": "…", "meaning": "Further dimension code (see the catalog)"}]}, {"key": "t-corner", "title": "Head – radius", "rows": [{"code": "R#.#", "meaning": "FF: corner radius; EFF: programmed radius (Rg) for CAM"}]}, {"key": "t-length", "title": "Head – length", "rows": [{"code": "L##", "meaning": "Head length"}]}, {"key": "t-flutes", "title": "Head – flutes", "rows": [{"code": "#", "meaning": "Number of flutes"}]}, {"key": "t-connection", "title": "MULTI-MASTER connection", "rows": [{"code": "T##", "meaning": "MULTI-MASTER thread connection size"}]}, {"key": "t-suffix", "title": "Head – suffix", "rows": [{"code": "H", "meaning": "With a central coolant hole"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
